import { type BoardStore, openBoardStore, type StoredObject } from "@stallion/client-store";
import type { BoardOptions, BoardStatus, LiveObjects, StallionBoard } from "@stallion/client-sync";
import { type BBox, viewTiles } from "@stallion/geometry";
import { errorMessage } from "./report";

export type Connection = "Connected" | "Reconnecting" | "Offline" | "LocalOnly";

export const CONNECTION_LABEL: Record<Connection, string> = {
  Connected: "Connected",
  Reconnecting: "Reconnecting",
  Offline: "Offline",
  LocalOnly: "Local only: strokes stay in this browser",
};

export const VIEW_DEBOUNCE_MS = 100;

export type Awareness = StallionBoard["awareness"];

export type BoardSource = {
  view(viewport: BBox, zoom: number): void;
  commit(stored: StoredObject): void;
  erase(objectId: string): void;
  readonly objects: LiveObjects;
  readonly awareness: Awareness | undefined;
  close(): Promise<void>;
};

export type OpenBoard = (url: string, boardId: string, options?: BoardOptions) => StallionBoard;

export type SourceOptions = {
  url: string | undefined;
  boardId: string;
  openBoard: OpenBoard;
  onConnection: (connection: Connection) => void;
  onError: (message: string) => void;
};

export const connectionFor = (status: BoardStatus, online: boolean): Connection => {
  if (status === "Open") return "Connected";
  if (!online) return "Offline";
  return status === "Closed" ? "Offline" : "Reconnecting";
};

const liveObjects = (): {
  objects: LiveObjects;
  map: Map<string, StoredObject>;
  notify: (changed: ReadonlySet<string>) => void;
} => {
  const map = new Map<string, StoredObject>();
  const listeners = new Set<(changed: ReadonlySet<string>) => void>();
  const objects: LiveObjects = Object.assign(map, {
    observe(listener: (changed: ReadonlySet<string>) => void): () => void {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  });
  const notify = (changed: ReadonlySet<string>): void => {
    if (changed.size === 0) return;
    for (const listener of listeners) listener(changed);
  };
  return { objects, map, notify };
};

const debounced = (run: (viewport: BBox, zoom: number) => void) => {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return {
    call(viewport: BBox, zoom: number): void {
      clearTimeout(timer);
      timer = setTimeout(() => run(viewport, zoom), VIEW_DEBOUNCE_MS);
    },
    cancel(): void {
      clearTimeout(timer);
    },
  };
};

export function openLocalSource(boardId: string, onError: (message: string) => void): BoardSource {
  const { objects, map, notify } = liveObjects();
  const removed = new Set<string>();
  const storeReady: Promise<BoardStore> = openBoardStore(boardId);
  const fail = (action: string) => (error: unknown) => onError(`${action}: ${errorMessage(error)}`);
  storeReady.catch(fail("Could not open the local board storage"));

  const setView = debounced((viewport, zoom) => {
    const tiles = viewTiles(viewport, zoom);
    storeReady
      .then((store) => store.query([...tiles.live, ...tiles.snapshot]))
      .then((found) => {
        const changed = new Set<string>();
        for (const stored of found) {
          const { objectId } = stored.object;
          if (map.has(objectId) || removed.has(objectId)) continue;
          map.set(objectId, stored);
          changed.add(objectId);
        }
        notify(changed);
      })
      .catch(fail("Could not load the board from local storage"));
  });

  return {
    view: setView.call,
    commit(stored) {
      map.set(stored.object.objectId, stored);
      notify(new Set([stored.object.objectId]));
      storeReady
        .then((store) => store.put(stored))
        .catch(fail("Could not save the stroke to local storage"));
    },
    erase(objectId) {
      const stored = map.get(objectId);
      if (!stored) return;
      removed.add(objectId);
      map.delete(objectId);
      notify(new Set([objectId]));
      storeReady
        .then((store) => store.remove(objectId, stored.tile))
        .catch(fail("Could not delete the stroke from local storage"));
    },
    objects,
    awareness: undefined,
    async close() {
      setView.cancel();
      await storeReady.then(
        (store) => store.close(),
        () => undefined,
      );
    },
  };
}

export function openSyncSource(url: string, options: SourceOptions): BoardSource {
  const online = () => globalThis.navigator?.onLine !== false;
  const board = options.openBoard(url, options.boardId, {
    onStatus: (status) => options.onConnection(connectionFor(status, online())),
    onError: ({ tileKey, reason }) =>
      options.onError(`Sync failed${tileKey ? ` on tile ${tileKey}` : ""}: ${reason}`),
  });
  options.onConnection(connectionFor(board.status, online()));
  const setView = debounced((viewport, zoom) => board.setView(viewport, zoom));
  return {
    view: setView.call,
    commit: (stored) => board.put(stored),
    erase: (objectId) => board.remove(objectId),
    objects: board.objects,
    awareness: board.awareness,
    close() {
      setView.cancel();
      return board.close();
    },
  };
}

export function openSource(options: SourceOptions): BoardSource {
  if (!options.url) {
    options.onConnection("LocalOnly");
    return openLocalSource(options.boardId, options.onError);
  }
  try {
    return openSyncSource(options.url, options);
  } catch (error) {
    options.onError(
      `Could not connect to ${options.url} (${errorMessage(error)}), working local only`,
    );
    options.onConnection("LocalOnly");
    return openLocalSource(options.boardId, options.onError);
  }
}
import { PALETTE, PENCIL_SIZES } from "./stroke";
import type { Tool } from "./surface";
import { CONNECTION_LABEL, type Connection } from "./sync";

const DOT_PX = { Small: 4, Medium: 9, Large: 16 } as const;

type ToolbarProps = { tool: Tool; onChange: (tool: Tool) => void; connection: Connection };

export function Toolbar({ tool, onChange, connection }: ToolbarProps) {
  return (
    <div class="toolbar" role="toolbar" aria-label="Drawing tools">
      <fieldset class="group" aria-label="Pencil size">
        {PENCIL_SIZES.map((size) => (
          <button
            key={size}
            type="button"
            aria-pressed={tool.mode === "Pencil" && tool.size === size}
            aria-label={`${size} pencil`}
            class="tool"
            onClick={() => onChange({ ...tool, size, mode: "Pencil" })}
          >
            <span class="dot" style={{ width: DOT_PX[size], height: DOT_PX[size] }} />
          </button>
        ))}
      </fieldset>
      <fieldset class="group" aria-label="Colour">
        {PALETTE.map((colour, index) => (
          <button
            key={colour}
            type="button"
            aria-pressed={tool.primary === index}
            aria-label={`Colour ${index + 1}`}
            title="Tap for primary, right-click or long-press for secondary"
            class={tool.secondary === index ? "tool swatch secondary" : "tool swatch"}
            style={{ background: colour }}
            onClick={() => onChange({ ...tool, primary: index })}
            onContextMenu={(event) => {
              event.preventDefault();
              onChange({ ...tool, secondary: index });
            }}
          />
        ))}
      </fieldset>
      <button
        type="button"
        class="tool"
        aria-pressed={tool.mode === "Pan"}
        aria-label="Pan tool"
        title="Drag with one finger to move the board"
        onClick={() => onChange({ ...tool, mode: tool.mode === "Pan" ? "Pencil" : "Pan" })}
      >
        <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
          <path
            d="M12 2v20M2 12h20M12 2l-3 3M12 2l3 3M12 22l-3-3M12 22l3-3M2 12l3-3M2 12l3 3M22 12l-3-3M22 12l-3 3"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
          />
        </svg>
      </button>
      <button
        type="button"
        class="tool"
        aria-pressed={tool.mode === "Eraser"}
        aria-label="Eraser"
        title="Tap or drag across a stroke to delete it"
        onClick={() => onChange({ ...tool, mode: tool.mode === "Eraser" ? "Pencil" : "Eraser" })}
      >
        <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
          <path
            d="M16 3l5 5-11 11H5l-3-3L16 3zM9 10l5 5M10 21h11"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linejoin="round"
            stroke-linecap="round"
          />
        </svg>
      </button>
      <button
        type="button"
        class="tool pair"
        aria-label="Swap primary and secondary colour"
        onClick={() => onChange({ ...tool, primary: tool.secondary, secondary: tool.primary })}
      >
        <span class="chip back" style={{ background: PALETTE[tool.secondary] }} />
        <span class="chip front" style={{ background: PALETTE[tool.primary] }} />
      </button>
      <span
        class="status"
        data-connection={connection}
        role="status"
        aria-label={CONNECTION_LABEL[connection]}
        title={CONNECTION_LABEL[connection]}
      />
    </div>
  );
}
import { Redirect, Route, Switch } from "wouter-preact";
import { Board } from "./board";

export const DEFAULT_BOARD = "default";

export function App() {
  return (
    <Switch>
      <Route path="/b/:boardId">
        {(params) => <Board key={params.boardId} boardId={params.boardId} />}
      </Route>
      <Route>
        <Redirect to={`/b/${DEFAULT_BOARD}`} replace />
      </Route>
    </Switch>
  );
}
/// <reference types="vite/client" />

interface ImportMetaEnv {
  readonly VITE_SYNC_URL?: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}
import type { StoredObject } from "@stallion/client-store";
import type { StallionBoard } from "@stallion/client-sync";
import { expect, test, vi } from "vitest";
import { type OpenBoard, openSource } from "./sync";

const stored: StoredObject = {
  tile: { level: 0, tx: 0, ty: 0 },
  object: {
    type: "Stroke",
    objectId: "000000000aaaaaaaaaaaa",
    nativeZoom: 0,
    bbox: { minX: 0, minY: 0, maxX: 10, maxY: 10 },
    colour: 0,
    size: "Medium",
    points: [[1, 1, 0.5]],
  },
};

test("a stroke commit goes through put and an erase through remove", () => {
  const put = vi.fn();
  const remove = vi.fn();
  const openBoard: OpenBoard = (url, boardId) => {
    expect([url, boardId]).toEqual(["ws://sync.test", "board"]);
    return { put, remove, status: "Connecting" } as unknown as StallionBoard;
  };
  const connections: string[] = [];
  const source = openSource({
    url: "ws://sync.test",
    boardId: "board",
    openBoard,
    onConnection: (connection) => connections.push(connection),
    onError: (message) => {
      throw new Error(message);
    },
  });

  source.commit(stored);
  source.erase(stored.object.objectId);

  expect(put).toHaveBeenCalledWith(stored);
  expect(remove).toHaveBeenCalledWith(stored.object.objectId);
  expect(connections).toEqual(["Reconnecting"]);
});
